#include <string>

using namespace std;

class Solution {
public:
    string freqAlphabets(string s) {
        string res;
        for (int i = s.size() - 1; i >= 0; --i) {
            if (s[i] == '#') {
                int val = stoi(s.substr(i - 2, 2));
                res += 'a' + val - 1;
                i -= 2;
            } else {
                res += 'a' + (s[i] - '0') - 1;
            }
        }
        reverse(res.begin(), res.end());
        return res;
    }
};
